22	// Cached agents to avoid recreating on every request.
23	// Keep separate entries per resolved connection count so overlapping requests
24	// with different request-scoped concurrency caps do not evict each other.
25	// Without caching, concurrent requests race on setGlobalDispatcher(),
26	// corrupting TLS session state and producing "bad record mac" errors.
27	//
28	// Note: TLS options (rejectUnauthorized, CA cert) are captured at agent
29	// creation time. This is acceptable because these env vars don't change
30	// mid-process. If that assumption changes, add cache-invalidation logic.
31	const cachedAgents: Map<number, Agent> = new Map();
32	const cachedProxyAgents: Map<string, ProxyAgent> = new Map();
33	
34	/**
35	 * Get the connection pool size for HTTP agents.
36	 * Priority: PROMPTFOO_FETCH_CONNECTIONS env var > CLI -j flag > DEFAULT_MAX_CONCURRENCY (4).
37	 * Set PROMPTFOO_FETCH_CONNECTIONS to override independently of eval concurrency
38	 * (e.g., server deployments that need more connections than the default 4).
39	 */
40	function getConnectionPoolSize(): number {
41	  const envConnections = getEnvString('PROMPTFOO_FETCH_CONNECTIONS');
42	  if (envConnections != null) {
43	    const parsed = parseInt(envConnections, 10);
44	    if (!isNaN(parsed)) {
45	      return parsed;
46	    }
47	  }
48	  return cliState.maxConcurrency || DEFAULT_MAX_CONCURRENCY;
49	}
