51	/**
52	 * Clear cached agents so the next request creates fresh ones.
53	 * Exported for testing only.
54	 */
55	export function clearAgentCache(): void {
56	  for (const agent of cachedAgents.values()) {
57	    if (typeof agent.close === 'function') {
58	      agent.close();
59	    }
60	  }
61	  cachedAgents.clear();
62	  for (const agent of cachedProxyAgents.values()) {
63	    if (typeof agent.close === 'function') {
64	      agent.close();
65	    }
66	  }
67	  cachedProxyAgents.clear();
68	}
