70	function getOrCreateAgent(tlsOptions: ConnectionOptions): Agent {
71	  const concurrency = getConnectionPoolSize();
72	  const existing = cachedAgents.get(concurrency);
73	  if (existing) {
74	    return existing;
75	  }
76	  const agent = new Agent({
77	    headersTimeout: REQUEST_TIMEOUT_MS,
78	    keepAliveTimeout: 30_000,
79	    keepAliveMaxTimeout: 60_000,
80	    connections: concurrency,
81	    connect: tlsOptions,
82	  });
83	  cachedAgents.set(concurrency, agent);
84	  return agent;
85	}
