91	function getOrCreateProxyAgent(proxyUrl: string, tlsOptions: ConnectionOptions): ProxyAgent {
92	  const concurrency = getConnectionPoolSize();
93	  const cacheKey = getProxyAgentCacheKey(proxyUrl, concurrency);
94	  const existing = cachedProxyAgents.get(cacheKey);
95	  if (existing) {
96	    return existing;
97	  }
98	  const agent = new ProxyAgent({
99	    uri: proxyUrl,
100	    proxyTls: tlsOptions,
101	    requestTls: tlsOptions,
102	    headersTimeout: REQUEST_TIMEOUT_MS,
103	    keepAliveTimeout: 30_000,
104	    keepAliveMaxTimeout: 60_000,
105	    connections: concurrency,
106	  });
107	  cachedProxyAgents.set(cacheKey, agent);
108	  return agent;
109	}
