111	/**
112	 * Resolve whether to disable transient-error retries. An explicit caller flag
113	 * always wins (a caller may opt back in even when the provider set
114	 * `maxRetries: 0`); otherwise we disable only when the retry context carries
115	 * `maxRetries === 0`.
116	 */
117	function resolveTransientRetryDisabled(explicit?: boolean): boolean {
118	  if (explicit !== undefined) {
119	    return explicit;
120	  }
121	  return getFetchRetryContextMaxRetries() === 0;
122	}
