148	      : abortSignal
149	    : options.signal;
150	
151	  // This is overridden globally but Node v20 is still complaining so we need to add it here too
152	  const finalOptions: FetchOptions & { dispatcher?: any } = {
153	    ...options,
154	    headers: {
155	      ...(options.headers as Record<string, string>),
156	      'x-promptfoo-version': VERSION,
157	    },
158	    signal: combinedSignal,
159	  };
