168	        ) {
169	          logger.warn(
170	            'Both URL credentials and Authorization header present - URL credentials will be ignored',
171	          );
172	        } else {
173	          // Move credentials to Authorization header
174	          const username = parsedUrl.username || '';
175	          const password = parsedUrl.password || '';
176	          const credentials = Buffer.from(`${username}:${password}`).toString('base64');
177	          finalOptions.headers = {
178	            ...(finalOptions.headers as Record<string, string>),
179	            Authorization: `Basic ${credentials}`,
180	          };
181	        }
182	        parsedUrl.username = '';
183	        parsedUrl.password = '';
184	        finalUrl = parsedUrl.toString();
185	        finalUrlString = finalUrl.toString();
186	      }
187	    } catch (e) {
188	      logger.debug(`URL parsing failed in fetchWithProxy: ${e}`);
189	    }
190	  }
191	
192	  const tlsOptions: ConnectionOptions = {
193	    rejectUnauthorized: !getEnvBool('PROMPTFOO_INSECURE_SSL', true),
194	  };
195	
196	  // Support custom CA certificates
197	  const caCertPath = getEnvString('PROMPTFOO_CA_CERT_PATH');
198	  if (caCertPath) {
199	    try {
200	      const resolvedPath = path.resolve(cliState.basePath || '', caCertPath);
201	      const ca = await fsPromises.readFile(resolvedPath, 'utf8');
