12	function isConnectionError(error: Error) {
13	  return (
14	    error instanceof TypeError &&
15	    error.message === 'fetch failed' &&
16	    // @ts-expect-error undici error cause
17	    error.cause?.stack?.includes('internalConnectMultiple')
18	  );
