21	/**
22	 * Enhanced fetch wrapper that adds logging, authentication, error handling, and optional compression
23	 */
24	
25	export async function monkeyPatchFetch(
26	  url: string | URL | Request,
27	  options?: FetchOptions,
28	): Promise<Response> {
29	  const NO_LOG_URLS = [R_ENDPOINT, CONSENT_ENDPOINT, EVENTS_ENDPOINT];
30	  const headers = (options?.headers as Record<string, string>) || {};
31	  const isSilent = headers['x-promptfoo-silent'] === 'true';
32	  const logEnabled = !NO_LOG_URLS.some((logUrl) => url.toString().startsWith(logUrl)) && !isSilent;
33	
34	  const opts: RequestInit = {
35	    ...options,
36	  };
37	
38	  const originalBody = opts.body;
39	
40	  // Handle compression if requested
41	  if (options?.compress && opts.body && typeof opts.body === 'string') {
42	    try {
43	      const compressed = await gzipAsync(opts.body);
44	      opts.body = compressed as BodyInit;
45	      opts.headers = {
46	        ...(opts.headers || {}),
47	        'Content-Encoding': 'gzip',
48	      };
49	    } catch (e) {
50	      logger.warn(`Failed to compress request body: ${e}`);
51	    }
52	  }
53	
54	  if (
55	    (typeof url === 'string' && url.startsWith(CLOUD_API_HOST)) ||
56	    (url instanceof URL && url.host === CLOUD_API_HOST.replace(/^https?:\/\//, ''))
57	  ) {
58	    const token = cloudConfig.getApiKey();
59	    opts.headers = {
60	      ...(opts.headers || {}),
61	      ...(token ? { Authorization: `Bearer ${token}` } : {}),
62	    };
63	  }
64	  try {
65	    // biome-ignore lint/style/noRestrictedGlobals: we need raw fetch here
66	    const response = await fetch(url, opts);
67	
68	    if (logEnabled) {
69	      void logRequestResponse({
70	        url: url.toString(),
71	        requestBody: originalBody,
72	        requestMethod: opts.method || 'GET',
73	        response,
74	      });
75	    }
76	
77	    return response;
78	  } catch (e) {
79	    if (logEnabled) {
80	      void logRequestResponse({
81	        url: url.toString(),
82	        requestBody: opts.body,
83	        requestMethod: opts.method || 'GET',
84	        response: null,
85	      });
86	      if (isConnectionError(e as Error)) {
87	        logger.debug(
88	          `Connection error, please check your network connectivity to the host: ${url} ${process.env.HTTP_PROXY || process.env.HTTPS_PROXY ? `or Proxy: ${process.env.HTTP_PROXY || process.env.HTTPS_PROXY}` : ''}`,
89	        );
90	        throw e;
91	      }
92	      logger.debug(
93	        `Error in fetch: ${JSON.stringify(e, Object.getOwnPropertyNames(e), 2)} ${e instanceof Error ? e.stack : ''}`,
94	      );
95	    }
96	    throw e;
97	  }
98	}
